/**
 * @brief Consulta la cima sin modificar la pila.
 * @param p Pila a consultar; puede ser NULL.
 * @return Valor de la cima, o -1 si está vacía. El valor -1 también puede estar almacenado.
 */
int pila_cima(ptrPila p) {
    return p == NULL ? -1 : p->nro;
}

